//! 真实 GPU 导出冒烟测试。
//!
//! CI 的 Windows runner 没有可用 GPU, 所以默认跳过; 本地要验证内嵌 shader 的渲染链路时:
//!
//! ```text
//! $env:WEBGAL_RENDER_GPU_TEST = "1"
//! cargo test -p webgal-video-render-sys --test export_video -- --nocapture
//! ```
//!
//! 想导出别的项目 (例如实机验收用的示例工程) 时再给两个变量:
//!
//! ```text
//! $env:WEBGAL_RENDER_GPU_PROJECT = "C:\path\to\project"
//! $env:WEBGAL_RENDER_GPU_LIVE2D_CORE = "C:\path\Live2DCubismCore.dll"   # 有 Live2D 立绘时需要
//! ```

use std::{path::PathBuf, sync::atomic::AtomicBool};

use webgal_video_export::api::{ExportOptions, build_plan};
use webgal_video_render_sys::{Callbacks, RenderOptions, from_plan, render};

fn fixture() -> PathBuf {
    if let Some(path) = std::env::var_os("WEBGAL_RENDER_GPU_PROJECT") {
        return PathBuf::from(path);
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../webgal-video-export/tests/fixtures/minimal")
}

/// 自定义项目保持原分辨率与帧率, 内置 fixture 则压到 320×180 / 10fps 让测试快一点。
fn is_custom_project() -> bool {
    std::env::var_os("WEBGAL_RENDER_GPU_PROJECT").is_some()
}

fn gpu_test_enabled() -> bool {
    std::env::var_os("WEBGAL_RENDER_GPU_TEST").is_some()
}

#[test]
fn exports_mp4_from_fixture_project() {
    if !gpu_test_enabled() {
        eprintln!("跳过 GPU 导出测试; 设置 WEBGAL_RENDER_GPU_TEST=1 以启用");
        return;
    }

    let mut options = ExportOptions::new(fixture());
    if let Some(height) = std::env::var("WEBGAL_RENDER_GPU_RESOLUTION")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
    {
        // 模拟 Ink 的分辨率预设: 只给高度, 宽度按舞台宽高比推导。
        options.config.video.auto_width = true;
        options.config.video.height = height;
        options.config.video.width = 0;
    } else if !is_custom_project() || std::env::var_os("WEBGAL_RENDER_GPU_FAST").is_some() {
        options.config.video.width = 320;
        options.config.video.height = 180;
        options.config.video.fps = 10;
        options.config.playback_speed = 4.0;
    }
    if let Some(speed) = std::env::var("WEBGAL_RENDER_GPU_SPEED")
        .ok()
        .and_then(|value| value.parse::<f32>().ok())
    {
        // 验收时加速整条时间线, 只用于快速抽样 (动画时长会一起缩短)。
        options.config.playback_speed = speed;
    }
    let plan = build_plan(&options).expect("编译计划");
    assert!(plan.meta.duration_us > 0, "计划时长为 0");
    if let Some(height) = std::env::var("WEBGAL_RENDER_GPU_RESOLUTION")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
    {
        assert_eq!(plan.meta.output_h, height, "输出高度应等于预设");
        assert_eq!(
            plan.meta.output_w / 2 * 9,
            plan.meta.output_h * 8,
            "16:9 舞台应保持画幅"
        );
    }

    let builder = from_plan(&plan).expect("映射计划");
    // `WEBGAL_RENDER_GPU_OUTPUT` 指定时保留产物 (实机验收要把 MP4 拿出来看), 否则用临时文件。
    let keep_output = std::env::var_os("WEBGAL_RENDER_GPU_OUTPUT").map(PathBuf::from);
    let output = keep_output
        .clone()
        .unwrap_or_else(|| std::env::temp_dir().join("webgal-render-sys-gpu-test.mp4"));
    let _ = std::fs::remove_file(&output);

    let mut render_options = RenderOptions::new(&output);
    render_options.encoder = webgal_video_render_sys::Encoder::MediaFoundation;
    render_options.live2d_core =
        std::env::var_os("WEBGAL_RENDER_GPU_LIVE2D_CORE").map(PathBuf::from);
    // 指定日志文件时验证"目录不存在也能建出来"(Ink 用的是 %APPDATA%\...\logs\video-export.log)。
    let log_path = std::env::var_os("WEBGAL_RENDER_GPU_LOG").map(PathBuf::from);
    render_options.log = log_path.clone();

    // 同时验进度与预览回调: 两者都是前端"导出进度页"的数据源。
    let progress_count = std::sync::atomic::AtomicUsize::new(0);
    let previews: std::sync::Mutex<Vec<Vec<u8>>> = std::sync::Mutex::new(Vec::new());
    let progress = |_: webgal_video_render_sys::Progress<'_>| {
        progress_count.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    };
    let preview = |frame: webgal_video_render_sys::Preview<'_>| {
        previews
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .push(frame.png.to_vec());
    };
    let encoder_name = std::sync::Mutex::new(None);
    let encoder = |name: &str| {
        *encoder_name
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(name.to_owned());
    };
    let callbacks = Callbacks {
        progress: Some(&progress),
        preview: Some(&preview),
        encoder: Some(&encoder),
        cancel: None,
    };
    let result = render(&builder, &render_options, callbacks);
    let size = std::fs::metadata(&output)
        .map(|meta| meta.len())
        .unwrap_or(0);
    if keep_output.is_none() {
        let _ = std::fs::remove_file(&output);
    }
    if let Some(path) = &log_path {
        assert!(path.is_file(), "日志文件应被创建: {}", path.display());
    }

    let previews = previews
        .into_inner()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    assert!(
        progress_count.load(std::sync::atomic::Ordering::Relaxed) > 0,
        "应上报进度"
    );
    assert!(!previews.is_empty(), "应推至少一帧预览");
    assert!(
        previews[0].starts_with(&[0x89, b'P', b'N', b'G']),
        "预览帧应是 PNG"
    );

    result.expect("导出 MP4 失败");
    assert!(size > 0, "MP4 为空");
    let encoder_name = encoder_name
        .into_inner()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    assert!(encoder_name.is_some(), "应上报实际编码后端");
    eprintln!(
        "导出成功: {size} 字节, 编码器 {:?} -> {}",
        encoder_name,
        output.display()
    );
}

#[test]
fn cancelled_export_reports_cancelled() {
    if !gpu_test_enabled() {
        return;
    }

    let mut options = ExportOptions::new(fixture());
    options.config.video.width = 320;
    options.config.video.height = 180;
    options.config.video.fps = 10;
    let plan = build_plan(&options).expect("编译计划");
    let builder = from_plan(&plan).expect("映射计划");

    let output = std::env::temp_dir().join("webgal-render-sys-gpu-cancel.mp4");
    let _ = std::fs::remove_file(&output);
    let render_options = RenderOptions::new(&output);

    // 一开始就取消: 渲染器应在第一个检查点停下并回报 Cancelled.
    let cancel = AtomicBool::new(true);
    let result = render(
        &builder,
        &render_options,
        Callbacks {
            progress: None,
            preview: None,
            encoder: None,
            cancel: Some(&cancel),
        },
    );
    let _ = std::fs::remove_file(&output);

    let error = result.expect_err("取消后不应成功");
    assert_eq!(error.status(), webgal_video_render_sys::Status::Cancelled);
}
